(()=>{
'use strict';
const K=window.KingdomSim,N=window.NavalUI,A=window.KingdomArt,$=id=>document.getElementById(id);let api;
const difficultyOptions='<option value="global">跟随整体难度</option>'+Object.entries(K.difficulties).map(([id,p])=>'<option value="'+id+'">'+p.name+'</option>').join('');
$('difficulty').innerHTML=Object.entries(K.difficulties).map(([id,p])=>'<option value="'+id+'">'+p.name+(id==='beginner'?' · 推荐初次游玩':'')+'</option>').join('');$('difficulty').value='beginner';$('ai-count').value='1';$('ai-count').dispatchEvent(new Event('change',{bubbles:true}));
for(let t=1;t<=3;t++){const select=document.createElement('select');select.id='ai-level-'+t;select.setAttribute('aria-label','电脑 '+t+' 难度');select.innerHTML=difficultyOptions;$('ai-nation-'+t).parentElement.append(select)}
const detail=document.createElement('p');detail.id='difficulty-detail';document.querySelector('.difficulty').after(detail);
function describeDifficulty(){const p=K.difficulties[$('difficulty').value];detail.textContent=p.description+'。电脑采集 '+Math.round(p.economy*100)+'%，伤害 '+Math.round(p.damage*100)+'%，军队人口最多 '+p.cap+'。保护期双方不能交战。'}
$('difficulty').addEventListener('change',describeDifficulty);describeDifficulty();
const getOptions=N.options.bind(N),restore=N.restore.bind(N),bind=N.bind.bind(N);N.options=()=>{const o=getOptions();o.difficulties=[null,...[1,2,3].slice(0,o.nations.length-1).map(t=>$('ai-level-'+t).value==='global'?$('difficulty').value:$('ai-level-'+t).value)];return o};N.restore=s=>{restore(s);$('difficulty').value=K.difficulties[s.difficulty]?s.difficulty:'beginner';for(let t=1;t<s.nations.length;t++)$('ai-level-'+t).value=s.aiDifficulties?.[t]||'global';describeDifficulty()};N.bind=value=>{api=value;bind(value)};
const protection=document.createElement('div');protection.id='protection-banner';protection.textContent='入门模式 · 20:00 保护期';document.querySelector('.battlefield').append(protection);
window.DynastyUI={status(sim){const left=sim.protectionLeft();protection.dataset.safe=String(left>0);protection.textContent=left===Infinity?'沙盒模式 · 永久保护，双方不交战':left>0?'保护期 '+Math.floor(left/60).toString().padStart(2,'0')+':'+Math.floor(left%60).toString().padStart(2,'0')+' · 安心发展，暂不交战':'保护期结束 · 可交战与贸易';}};
const change=document.createElement('button');change.id='change-difficulty';change.className='secondary';change.textContent='调整电脑难度';$('new-game').after(change);
const levelDialog=document.createElement('dialog');levelDialog.id='level-dialog';levelDialog.innerHTML='<div class="diplomacy-head"><div><small>DIFFICULTY</small><h2>调整电脑难度</h2></div><button id="close-level" aria-label="关闭难度设置">×</button></div><p>降低难度会停止当前电脑进军，并重新给予该档保护期。保留你的建筑、资源与研究。</p><label>全部电脑 <select id="live-level">'+Object.entries(K.difficulties).map(([id,p])=>'<option value="'+id+'">'+p.name+'</option>').join('')+'</select></label><button id="apply-level">应用难度</button><p id="level-feedback" role="status"></p>';document.body.append(levelDialog);change.onclick=()=>{$('live-level').value='beginner';levelDialog.showModal()};$('close-level').onclick=()=>levelDialog.close();$('apply-level').onclick=()=>{const sim=api.getSim(),out=[];for(let t=1;t<sim.state.nations.length;t++)out.push(sim.setDifficulty(t,$('live-level').value));$('level-feedback').textContent=out.join('；');api.refresh()};
const guideButton=document.createElement('button');guideButton.className='secondary';guideButton.id='empire-guide';guideButton.textContent='查看十国 · 科技与英雄图鉴';$('start').before(guideButton);const pauseGuide=guideButton.cloneNode(true);pauseGuide.id='pause-guide';$('audio-settings').after(pauseGuide);
const guide=document.createElement('dialog');guide.id='empire-guide-dialog';guide.innerHTML='<div class="diplomacy-head"><div><small>IMPERIAL CODEX</small><h2>十国与五时代</h2></div><button id="close-guide" aria-label="关闭帝国图鉴">×</button></div><p>架空历史混合战役：美国等后期国家可与早期国家同场竞技。国家不等于队伍，旗帜下方色条表示队伍玩家。</p><label>查看国家 <select id="guide-nation">'+Object.values(K.nations).map(n=>'<option value="'+n.id+'">'+n.name+'</option>').join('')+'</select></label><div id="guide-country"></div><section id="guide-eras"><h3>时代与研发</h3><p>I 开拓：采集、市场、商队与初级部队。</p><p>II 殖民：国家特色建筑与兵种，骑兵、医师、铁匠铺。</p><p>III 要塞：炮兵、重舰、国家专属学说。</p><p>IV 帝国：皇家大学、近卫兵工厂；近卫戟兵、龙骑兵、工程师；弹道、后勤、野战医疗、棱堡筑城。</p><p>V 传奇：皇家铸炮厂、国家统帅府；重型榴弹炮、国家英雄；爆破弹药与统帅学。</p><p>后期解锁依然需要实际支付食物、木材、黄金与石料。英雄占 6 人口，每国一名，阵亡重招等待 180 秒；技能消耗黄金。</p></section>';document.body.append(guide);
function renderGuide(){const n=K.nations[$('guide-nation').value],u=K.defs[n.unique],hero=K.defs[n.hero],b=K.defs[n.building];$('guide-country').innerHTML='<div class="codex-country"><img alt="'+n.name+'建筑" src="'+A.icon(n.building)+'"><div><h3>'+n.flag+' '+n.name+'</h3><p>'+n.bonus+'</p><p>取舍：'+n.tradeoff+'</p><p>'+n.description+'</p></div></div><div class="codex-units"><article><img alt="'+u.name+'" src="'+A.icon(n.unique)+'"><h3>'+u.name+'</h3><p>'+u.description+'</p><small>生命 '+u.hp+' · 攻击 '+u.damage+' · 射程 '+u.range+'</small></article><article><img alt="'+hero.name+'" src="'+A.icon(n.hero)+'"><h3>'+hero.name+'</h3><p>'+n.skill.name+'：'+n.skill.text+'</p><small>'+n.skill.cost+' 黄金 · 冷却 '+n.skill.cooldown+' 秒</small></article></div><p>特色建筑：'+b.name+' · 国家研发：'+n.doctrine+'（'+n.doctrineText+'）</p>'}
function openGuide(){renderGuide();guide.showModal()}guideButton.onclick=openGuide;pauseGuide.onclick=openGuide;$('guide-nation').onchange=renderGuide;$('close-guide').onclick=()=>guide.close();
A.ready.then(()=>{for(const n of Object.values(K.nations)){const card=document.querySelector('.nation-card[data-nation="'+n.id+'"]');if(card){const image=document.createElement('img');image.alt=n.name+'特色兵种';image.src=A.icon(n.unique);card.prepend(image)}}}).catch(()=>{});
})();
